const inputData = $input.first().json;
const context = $('Normalizar Variáveis').first().json;
let parsed = null;

// Se houve erro na API do Gemini (ex: 503 alta demanda ou 429 quota)
if (inputData && inputData.error) {
  parsed = null;
} else if (inputData && Array.isArray(inputData.slides) && inputData.slides.length > 0) {
  parsed = inputData;
} else if (inputData && inputData.output && Array.isArray(inputData.output.slides)) {
  parsed = inputData.output;
} else {
  let rawText = '';
  if (typeof inputData === 'string') rawText = inputData;
  else if (inputData?.text) rawText = inputData.text;
  else if (inputData?.content?.parts?.[0]?.text) rawText = inputData.content.parts[0].text;
  else if (inputData?.candidates?.[0]?.content?.parts?.[0]?.text) rawText = inputData.candidates[0].content.parts[0].text;
  else if (inputData?.response) rawText = typeof inputData.response === 'string' ? inputData.response : JSON.stringify(inputData.response);
  else rawText = JSON.stringify(inputData);

  rawText = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();
  const jsonMatch = rawText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try { parsed = JSON.parse(jsonMatch[0]); } catch (e) { parsed = null; }
  }
}

// Fallback estratégico dinâmico se a IA externa estiver indisponível
if (!parsed || !Array.isArray(parsed.slides) || parsed.slides.length === 0) {
  const theme = context.theme || 'Alta Performance B2B';
  const audience = context.targetAudience || 'Decisores e Líderes';
  parsed = {
    hookHeadline: `${theme}: O Dossiê Estratégico de Impacto`,
    bodyCopy: `No cenário corporativo atual, dominar ${theme} exige precisão operacional, clareza de gargalos e execução consistente.\n\nConfira as diretrizes práticas detalhadas nas lâminas a seguir.`,
    ctaText: 'Salve este carrossel para consultar na sua próxima sessão de planejamento.',
    hashtags: [`#${theme.replace(/[^a-zA-Z0-9]/g, '')}`, '#EstrategiaB2B', '#AltaPerformance', '#BlackLink'],
    slides: [
      {
        slideNumber: 1,
        headline: `O Diagnóstico Real de ${theme}`,
        bodyText: 'Por que métodos convencionais perdem tração e como os líderes constroem vantagem competitiva.',
        visualPrompt: 'Minimal dark architectural structure, high contrast typography'
      },
      {
        slideNumber: 2,
        headline: 'O Gargalo Invisível na Operação',
        bodyText: 'Identifique onde o esforço do time é desperdiçado em processos manuais sem diferenciação de valor.',
        visualPrompt: 'Dark stone surface with crisp ambient side-lighting'
      },
      {
        slideNumber: 3,
        headline: 'A Estrutura de Domínio de Mercado',
        bodyText: 'Alinhe posicionamento de autoridade com esteiras de entrega previsíveis para proteger a margem.',
        visualPrompt: 'Sleek dark layout with refined spacing, modern typography'
      },
      {
        slideNumber: 4,
        headline: 'Execução Tática com Ritmo Sustentável',
        bodyText: 'Transforme diretrizes estratégicas em rotinas diárias com métricas claras de progresso e alinhamento.',
        visualPrompt: 'Matte graphite texture, minimalist line elements'
      },
      {
        slideNumber: 5,
        headline: 'A Próxima Fronteira de Decisão',
        bodyText: 'Aplique este roteiro no seu negócio e acelere o alcance dos seus objetivos com máxima segurança.',
        visualPrompt: 'Pure black background #030303, bold contrasting typography'
      }
    ]
  };
}

const crmBaseUrl = context.crmBaseUrl || 'https://blacklink-crm.netlify.app';
const totalSlides = parsed.slides ? parsed.slides.length : 5;

const slidesComImagens = (parsed.slides || []).map((slide, index) => {
  const slideNum = slide.slideNumber || index + 1;
  const h = encodeURIComponent(slide.headline || slide.title || '');
  const b = encodeURIComponent(slide.bodyText || slide.body || '');
  const f = encodeURIComponent(context.format || 'carousel');
  const query = `slide=${slideNum}&total=${totalSlides}&headline=${h}&body=${b}&format=${f}`;
  const imageUrl = `${crmBaseUrl}/api/marketing/render-slide?${query}`;
  return {
    slideNumber: slideNum,
    headline: slide.headline || slide.title || `Insight ${slideNum}`,
    bodyText: slide.bodyText || slide.body || '',
    visualPrompt: slide.visualPrompt || 'Dark minimal editorial aesthetic',
    imageUrl
  };
});

const hookHeadline = parsed.hookHeadline || slidesComImagens[0]?.headline || context.theme;
const bodyCopy = parsed.bodyCopy || 'Confira os detalhes neste carrossel estratégico.';
const ctaText = parsed.ctaText || 'Salve este post para consultar depois.';
const hashtags = Array.isArray(parsed.hashtags) ? parsed.hashtags : ['#VendasB2B', '#BlackLink', '#AltaPerformance'];
const postCaption = parsed.postCaption || `${bodyCopy}\n\n${ctaText}\n\n${hashtags.join(' ')}`;

return {
  id: `cr-n8n-${Date.now()}`,
  theme: context.theme,
  format: context.format,
  targetAudience: context.targetAudience,
  hookHeadline,
  bodyCopy,
  ctaText,
  hashtags,
  postCaption,
  slides: slidesComImagens,
  imageUrls: slidesComImagens.map(s => s.imageUrl),
  publishToInstagram: context.publishToInstagram,
  createdAt: new Date().toISOString(),
  source: 'n8n'
};

